#include <stdio.h>

#define MAX(a, b) ((a) > (b) ? (a) : (b))

static int read_count = 0;

// Читает следующее число; если чисел больше нет, возвращает -1000000.
int next_value(void) {
    int value;
    if (scanf("%d", &value) != 1) {
        return -1000000;
    }
    read_count++;
    return value;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    int best = -1000000;
    for (int i = 0; i < n; i++) {
        best = MAX(next_value(), best);
    }
    printf("максимум: %d\n", best);
    printf("прочитано чисел: %d\n", read_count);
    return 0;
}

