#include <stdio.h>

#define SUM_ARRAY(arr, n, result)              \
    do {                                       \
        long long acc_ = 0;                    \
        for (int i = 0; i < (n); i++) {        \
            acc_ += (arr)[i];                \
        }                                      \
        (result) = acc_;                       \
    } while (0)

int main(void) {
    int rows, cols;
    int m[10][10] = {{0}};
    long long sums[10];
    if (scanf("%d %d", &rows, &cols) != 2 || rows < 1 || rows > 10 || cols < 1 || cols > 10) {
        return 0;
    }
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (scanf("%d", &m[i][j]) != 1) {
                return 0;
            }
        }
    }
    long long total = 0;
    for (int i = 0; i < rows; i++) {
        SUM_ARRAY(m[i], cols, sums[i]);
        total += sums[i];
    }
    for (int i = 0; i < rows; i++) {
        printf("строка %d: %lld\n", i + 1, sums[i]);
    }
    printf("всего: %lld\n", total);
    return 0;
}

